add_action( 'woocommerce_before_add_to_cart_quantity', 'perfectpixel_gift_checkbox' );
add_filter( 'woocommerce_add_cart_item_data', 'perfectpixel_gift_cart_data' );
add_filter( 'woocommerce_get_item_data', 'perfectpixel_gift_item_data', 10, 2 );
add_action( 'woocommerce_checkout_create_order_line_item', 'perfectpixel_gift_order_meta', 10, 3 );
add_filter( 'woocommerce_ship_to_different_address_checked', 'perfectpixel_gift_ship_checked' );
add_filter( 'gettext_woocommerce', 'perfectpixel_gift_ship_heading', 10, 2 );

function perfectpixel_gift_checkbox() {
	echo '<p class="perfectpixel-gift" style="width:100%"><label><input type="checkbox" name="perfectpixel_gift" value="1"> ' . esc_html( '{{gift_checkbox_label}}' ) . '</label></p>';
}

function perfectpixel_gift_cart_data( $data ) {
	if ( ! empty( $_POST['perfectpixel_gift'] ) ) {
		$data['perfectpixel_gift'] = 1; // Gift and non-gift become separate cart lines.
	}
	return $data;
}

function perfectpixel_gift_item_data( $item_data, $cart_item ) {
	if ( ! empty( $cart_item['perfectpixel_gift'] ) ) {
		$item_data[] = array( 'key' => '{{gift_item_label}}', 'value' => '✓' );
	}
	return $item_data;
}

function perfectpixel_gift_order_meta( $item, $cart_item_key, $values ) {
	if ( ! empty( $values['perfectpixel_gift'] ) ) {
		$item->add_meta_data( '{{gift_item_label}}', '✓', true );
	}
}

function perfectpixel_gift_cart_has_gift() {
	if ( ! function_exists( 'WC' ) || ! WC()->cart ) {
		return false;
	}
	foreach ( WC()->cart->get_cart() as $item ) {
		if ( ! empty( $item['perfectpixel_gift'] ) ) {
			return true;
		}
	}
	return false;
}

function perfectpixel_gift_ship_checked( $checked ) {
	return perfectpixel_gift_cart_has_gift() ? true : $checked;
}

function perfectpixel_gift_ship_heading( $translation, $text ) {
	if ( 'Ship to a different address?' === $text && is_checkout() && perfectpixel_gift_cart_has_gift() ) {
		return '{{gift_ship_heading}}';
	}
	return $translation;
}
